package facturx

import "github.com/ritoon/zerechnung/internal/rules"

// Profile masks of the rules: the profiles whose official schematron holds
// the rule. mExt stands for EXTENDED and EXTENDED-CTC-FR; only EXTENDED gets
// the BR-FXEXT rules of the EXTENDED schematron (the code list assertions of
// mBasic, mEN and mExt only apply where the Factur-X schematron of the
// profile does, see Check); mOther for the other profiles (XRECHNUNG,
// PEPPOL), which only get the profile identification rules here.
const (
	mMin uint8 = 1 << iota
	mBWL
	mBasic
	mEN
	mExt
	mOther

	mLight = mMin | mBWL
	mAny   = mMin | mBWL | mBasic | mEN | mExt | mOther
)

// rule describes a rule of the package.
type rule struct {
	id   string
	sev  rules.Severity
	mask uint8
	fx   string // identifier of the assertion in the official Factur-X schematron, if any
	desc string
}

// table lists the rules. The identifiers are the business rule ones (BR-*,
// CII-SR-*) when the official assertion carries one, the identifier of the
// schematron assertion (FX-SCH-A-*) otherwise. The MINIMUM and BASIC WL
// schematrons only set a severity on the BR-FXEXT-*-08ini and -08rev
// assertions, which are warnings: every other assertion is an error.
